#!/bin/sh
# Checks that every proof obligation generated by hax is proven in Verification/.
#
# `lake build --wfail` only checks the files it compiles, and hax's template
# Extraction/ProofObligations.lean is never compiled. So this script checks, for
# every `theorem` in that template, that Verification/ contains a theorem with
# the same name AND the same statement (binders and type, whitespace ignored).
# That rules out a missing proof and a proof of a weaker statement under the
# right name. It also rejects any `axiom` in Verification/: an axiom states
# something without proof and produces no warning for --wfail to catch.
#
# The comparison is textual: it doesn't see `include`, `variable` or notation
# changes that alter what the same text means.
set -eu
cd "$(dirname "$0")"

template=LakersShared/Extraction/ProofObligations.lean
status=0

# Prints each `theorem` header, from `theorem` up to `:=`, joined onto one line
# with whitespace squeezed.
statements() {
  awk '
    /^theorem( |$)/ { s = ""; inside = 1 }
    inside {
      line = $0
      if (index(line, ":=")) { line = substr(line, 1, index(line, ":=") - 1); inside = 0 }
      s = s " " line
      if (!inside) { gsub(/[ \t]+/, " ", s); sub(/^ /, "", s); sub(/ $/, "", s); print s }
    }
  ' "$@"
}

# No template means no `ensures` yet, so there is nothing to prove.
if [ -f "$template" ]; then
  proofs=$(statements $(find LakersShared/Verification -name '*.lean'))
  # Fed by a here-document rather than a pipe, so the loop runs in this shell
  # and its `status=1` survives.
  while IFS= read -r stmt; do
    name=$(echo "$stmt" | cut -d' ' -f2)
    if ! printf '%s\n' "$proofs" | grep -qE "^theorem $name( |$)"; then
      echo "missing proof: $name"
      status=1
    elif ! printf '%s\n' "$proofs" | grep -qxF "$stmt"; then
      echo "statement differs from the template: $name"
      echo "  expected: $stmt"
      status=1
    fi
  done <<END
$(statements "$template")
END
fi

if grep -rnE '^\s*axiom ' LakersShared/Verification/; then
  echo "axioms are not allowed in Verification/"
  status=1
fi

exit $status
